using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class PaymentStatusHistoryConfiguration : IEntityTypeConfiguration<PaymentStatusHistory>
{
    public void Configure(EntityTypeBuilder<PaymentStatusHistory> builder)
    {
        //SQL table name
        builder.ToTable("PaymentStatusHistories");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //Foreign key configuration, PaymentId is required
        builder.Property(x => x.PaymentId).IsRequired();

        //FromStatus and ToStatus are required, have a maximum length defined, and are stored as strings in the database
        builder.Property(x => x.FromStatus).HasConversion<string>().HasMaxLength(Constants.MaxStatusLength).IsUnicode(false).IsRequired();
        builder.Property(x => x.ToStatus).HasConversion<string>().HasMaxLength(Constants.MaxStatusLength).IsUnicode(false).IsRequired();

        //Reason has a maximum length defined and can be null
        builder.Property(x => x.Reason).HasMaxLength(Constants.MaxReasonLength);

        //ChangedAtUtc is not null and is stored as UTC in the database
        builder.Property(x => x.ChangedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //PaymentStatusHistory has one Payment, and Payment has many PaymentStatusHistories
        //The foreign key is PaymentId, and on delete, the behavior is restricted
        builder.HasOne<Payment>().WithMany().HasForeignKey(x => x.PaymentId).OnDelete(DeleteBehavior.Restrict);

        //Index on PaymentId and ChangedAtUtc for faster queries
        //This index is useful for querying the status history of a payment in chronological order
        builder.HasIndex(x => new
        {
            x.PaymentId,
            x.ChangedAtUtc
        });
    }
}
